let body_content = nsCString::from(body.content.0);
body_stream
    .SetByteStringData(&raw const *body_content)
    .to_result()?;

// Set the stream as the channel's upload stream.
upload_channel
    .SetUploadStream(body_stream.coerce(), &raw const *content_type, len)
    .to_result()?;

let data = nsCString::from(data);
// SAFETY: data is a correctly formatted nsCString, and short enough to
// safely handle. We use `SetByteStringData()` here instead of one of
// the alternatives to ensure that the data is copied. Otherwise, the
// pointer may become invalid before the stream is dropped.
unsafe { stream.SetByteStringData(&raw const *data) }.to_result()?;
